def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'
    if n == 2:
        if sum(1 for a, b in history if b == 'D') >= 2:
            return 'D'
        return 'C'

    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    last_my, last_opp = history[-1]

    cycle_break = False
    if n >= 2 and last_my == 'C' and last_opp == 'D':
        if history[-2][0] == 'D' and history[-2][1] == 'C':
            cycle_break = True

    r5 = history[-5:] if n >= 5 else history
    r10 = history[-10:] if n >= 10 else history
    r5_opp_d = sum(1 for a, b in r5 if b == 'D')
    r10_opp_d = sum(1 for a, b in r10 if b == 'D')
    r5_opp_c = len(r5) - r5_opp_d
    r10_opp_c = len(r10) - r10_opp_d

    consec_opp_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_d += 1
        else:
            break

    forgive = 0
    punish = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                forgive += 1
            else:
                punish += 1

    if n == 98:
        if last_opp == 'D':
            if cycle_break and r10_opp_c >= 4:
                return 'C'
            return 'D'
        if opp_d == 0 and my_d >= 1:
            return 'D'
        if punish == 0 and forgive >= 2 and r10_opp_c >= 8:
            return 'D'
        if my_d >= 2 and opp_d <= 2 and r10_opp_c >= 8:
            return 'D'
        return 'C'

    if opp_d * 2 >= n or r10_opp_d >= 7 or (len(r5) >= 5 and r5_opp_d >= 4):
        if n >= 95 and last_opp == 'C' and r5_opp_c >= 4:
            return 'C'
        if last_opp == 'C' and r5_opp_c >= 4 and rng.random() < 0.15:
            return 'C'
        return 'D'

    if opp_d <= max(1, (n * 15) // 100):
        if my_d == 0 and opp_d == 0 and 70 < n < 93 and rng.random() < 0.02:
            return 'D'
        if last_opp == 'D':
            if cycle_break:
                return 'C'
            if last_my == 'D':
                return 'C'
            return 'D'
        if punish == 0 and forgive >= 2 and r5_opp_c == 5 and rng.random() < 0.05:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if cycle_break:
            return 'C'
        if last_my == 'D':
            if r10_opp_c >= 5 and rng.random() < 0.55:
                return 'C'
            return 'D'
        if r10_opp_c >= 8 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if r5_opp_d >= 3 or r10_opp_d >= 5:
        return 'D'
    if last_my == 'D' and punish == 0 and forgive >= 1 and r5_opp_c == 5 and rng.random() < 0.1:
        return 'D'
    return 'C'
